ALTER TABLE users ADD COLUMN is_admin INTEGER NOT NULL DEFAULT 0 CHECK (is_admin IN (0, 1));
ALTER TABLE users ADD COLUMN recovery_hash TEXT;
ALTER TABLE users ADD COLUMN auth_epoch INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN auth_mutation TEXT;
CREATE UNIQUE INDEX users_recovery_hash ON users(recovery_hash) WHERE recovery_hash IS NOT NULL;
CREATE TABLE auth_settings (id INTEGER PRIMARY KEY CHECK (id = 1), signup_open INTEGER NOT NULL DEFAULT 1 CHECK (signup_open IN (0, 1)), bootstrap_closed INTEGER NOT NULL DEFAULT 0 CHECK (bootstrap_closed IN (0, 1)), bootstrap_owner TEXT);
INSERT INTO auth_settings (id) VALUES (1);
CREATE TRIGGER bootstrap_permanent BEFORE UPDATE ON auth_settings WHEN OLD.bootstrap_closed = 1 AND (NEW.bootstrap_closed <> 1 OR NEW.bootstrap_owner IS NOT OLD.bootstrap_owner) BEGIN SELECT RAISE(ABORT, 'Administrator bootstrap is permanently closed'); END;
CREATE TRIGGER bootstrap_no_delete BEFORE DELETE ON auth_settings BEGIN SELECT RAISE(ABORT, 'Authentication policy cannot be deleted'); END;
CREATE TRIGGER bootstrap_no_replace BEFORE INSERT ON auth_settings WHEN EXISTS (SELECT 1 FROM auth_settings) BEGIN SELECT RAISE(ABORT, 'Authentication policy cannot be replaced'); END;
CREATE TABLE credentials (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, public_key TEXT NOT NULL, counter INTEGER NOT NULL CHECK (counter >= 0), transports_json TEXT NOT NULL, mutation_id TEXT);
CREATE INDEX credentials_user ON credentials(user_id);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), credential_id TEXT NOT NULL REFERENCES credentials(id) ON DELETE CASCADE, auth_epoch INTEGER NOT NULL, authenticated_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE auth_challenges (id TEXT PRIMARY KEY NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('signup', 'login', 'reauth', 'add', 'recover')), challenge TEXT NOT NULL, browser_hash TEXT NOT NULL, user_id TEXT, display_name TEXT, credential_name TEXT, session_hash TEXT, recovery_hash TEXT, user_epoch INTEGER, wants_admin INTEGER NOT NULL DEFAULT 0 CHECK (wants_admin IN (0, 1)), expires_at INTEGER NOT NULL, claim_token TEXT);
CREATE INDEX auth_challenges_expiry ON auth_challenges(expires_at);
CREATE TABLE auth_limits (key_hash TEXT PRIMARY KEY NOT NULL, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE INDEX auth_limits_expiry ON auth_limits(reset_at);
CREATE TRIGGER credential_last_access BEFORE DELETE ON credentials WHEN (SELECT COUNT(*) FROM credentials WHERE user_id = OLD.user_id) = 1 AND (SELECT recovery_hash FROM users WHERE id = OLD.user_id) IS NULL BEGIN SELECT RAISE(ABORT, 'Retain a usable account access method'); END;
